import React from 'react';
import Login from './components/Login';
import TestConnection from './components/TestConnection';

function App() {
  return (
    <div className="App">
      <TestConnection />
      <hr style={{ margin: '40px 0' }} />
      <Login />
    </div>
  );
}

export default App;
